<script setup lang="ts">import {computed} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import StatCard from '@/components/zs/StatCard.vue';import AsyncSection from '@/components/zs/AsyncSection.vue';import ActivityTimeline from '@/components/crm/ActivityTimeline.vue';import ScoreBadge from '@/components/crm/ScoreBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('CRM Overview','Sales pipeline, activity and tasks in one workspace.');const r=useRouter(),d=useCrmData();const leads=computed(()=>d.leads.data.value??[]),tasks=computed(()=>d.tasks.data.value??[]),acts=computed(()=>d.activities.data.value??[]);const open=computed(()=>leads.value.filter(x=>!['Won','Lost'].includes(x.stage)));const stages=['New','Contacted','Qualified','Proposal','Negotiation','Won','Lost'];</script>
<template><AppShell><PageHeader title="CRM Overview" description="Lead capture, qualification and outreach activity for this company"><template #actions><ZButton @click="r.push('/crm/capture')">Capture leads</ZButton><ZButton variant="outline" @click="r.push('/outreach/compose')">Create outreach</ZButton></template></PageHeader><AsyncSection :loading="d.loading.value" :error="d.leads.error.value" @retry="d.leads.refresh"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total leads" :value="String(leads.length)" tone="brand"/><StatCard label="New leads" :value="String(leads.filter(x=>x.stage==='New').length)"/><StatCard label="Qualified" :value="String(leads.filter(x=>x.stage==='Qualified').length)" tone="success"/><StatCard label="Pipeline value" :value="`PKR ${(open.reduce((s,x)=>s+x.value,0)/1000000).toFixed(1)}M`" tone="warning"/></div><div class="mt-3 grid gap-3 xl:grid-cols-[1.2fr_.8fr]"><Panel title="Pipeline overview" description="Current lead distribution"><div class="grid grid-cols-2 gap-px bg-line sm:grid-cols-4 xl:grid-cols-7"><button v-for="stage in stages" :key="stage" class="bg-surface p-4 text-left hover:bg-surface-hover" @click="r.push('/crm/pipeline')"><p class="label-caps">{{stage}}</p><p class="num mt-2 text-xl font-semibold text-content">{{leads.filter(x=>x.stage===stage).length}}</p><p class="mt-1 text-2xs text-content-muted">PKR {{(leads.filter(x=>x.stage===stage).reduce((s,x)=>s+x.value,0)/1000000).toFixed(1)}}M</p></button></div></Panel><Panel title="Tasks due" description="Follow-ups requiring attention"><ul class="divide-y divide-line px-4"><li v-for="task in tasks.filter(x=>x.status!=='Completed').slice(0,5)" :key="task.id" class="flex items-center justify-between gap-3 py-3"><div><p class="text-xs font-medium text-content">{{task.title}}</p><p class="text-2xs text-content-muted">{{task.relatedTo}} · {{task.owner}}</p></div><span class="num text-2xs text-content-muted">{{task.due}}</span></li></ul></Panel></div><div class="mt-3 grid gap-3 xl:grid-cols-[1.3fr_.7fr]"><Panel title="Recent activity" body-class="p-4"><ActivityTimeline :items="acts.slice(0,7)"/></Panel><Panel title="Highest-scoring leads"><ul class="divide-y divide-line px-4"><li v-for="lead in [...leads].sort((a,b)=>b.score.total-a.score.total).slice(0,6)" :key="lead.id" class="flex items-center justify-between gap-3 py-3"><button class="text-left" @click="r.push(`/crm/leads/${lead.id}`)"><p class="text-xs font-medium text-content">{{lead.name}}</p><p class="text-2xs text-content-muted">{{lead.company}}</p></button><ScoreBadge :score="lead.score.total"/></li></ul></Panel></div></AsyncSection></AppShell></template>
